 require(font.family()=="DejaVu Sans"&&font.pointSizeF()==24&&font.bold()&&font.italic(),"native save/reopen retains sheet font defaults beneath an authored bold-only cell style");require(style.value("fill",std::string())=="#FFEE00"&&style.value("color",std::string())=="#FF0000"&&style.value("numberFormat",std::string())=="0.00%"&&style.value("alignment",std::string())=="center"&&style.value("wrap",false)&&style.value("indent",0)==2&&style.value("border",Json::object()).contains("top"),"native save/reopen retains inherited colors, display format, alignment, wrapping, indent and borders for a partial style");require(restored.raw(2,1)=="0.25"&&restored.data(index).toString()=="25.00%","native style inheritance preserves numeric input and its displayed percentage");
