 WorkbookSession session(fixture());WorksheetModel model(session);QTableView view;view.setModel(&model);view.selectAll();const auto before=session.snapshot();require(formatWorksheetCells(nullptr,model,view,{{"style",{{"fontSize",12}}}}),"Format Cells supports a whole-worksheet font change");require(model.data(model.index(99999,999),Qt::FontRole).value<QFont>().pointSizeF()==12&&model.data(model.index(0,0),Qt::FontRole).value<QFont>().bold(),"whole-sheet formatting reaches blank cells while retaining mixed emphasis");require(session.snapshotView().at("sheets")[0].at("cells").size()==before.at("sheets")[0].at("cells").size()&&model.raw(0,0)=="'00123"&&model.cellStyle(0,0).at("note")=="Keep this note","whole-sheet formatting stays sparse and preserves inputs/notes");require(session.undo()&&session.snapshotView().at("sheets")==before.at("sheets"),"whole-sheet font and stored style edits are one Undo");
