void importedEscapedAccountingOptions(){
 const auto path=QFileInfo(QString::fromUtf8(__FILE__)).absoluteDir().absoluteFilePath("../tests/fixtures/biff/financial-source.xls");
 const auto source=readWorkbook(path.toStdString()).workbook;Json sourceStyle;
 for(const auto& sheet:source.at("sheets"))if(sheet.at("name")=="operations")for(const auto& cell:sheet.at("cells"))if(cell.at("row")==8&&cell.at("col")==7)sourceStyle=cell.at("style");
 require(sourceStyle.contains("numberFormat"),"actual BIFF Operations G8 retains its original Accounting format");
 const auto imported=sourceStyle.at("numberFormat").get<std::string>();require(imported.find("\\$")!=std::string::npos,"regression uses the original escaped-dollar Accounting format");
 auto book=fixture();book["sheets"][0]["cells"][0]["input"]="5648";book["sheets"][0]["cells"][0]["style"]["numberFormat"]=imported;
 WorkbookSession session(book);WorksheetModel model(session);QTableView view;view.setModel(&model);select(view,model,0,0,0,1);const auto before=session.snapshot();
 require(!withDialog(model,view,[&](QDialog* dialog){auto* category=dialog->findChild<QComboBox*>("formatCells.category");auto* symbol=dialog->findChild<QComboBox*>("formatCells.currencySymbol");require(category->currentData()=="accounting"&&symbol->currentData()=="$","imported escaped dollar is displayed as the actual dollar currency symbol");dialog->reject();})&&session.snapshot()==before&&!session.canUndo(),"merely inspecting imported Accounting preserves its exact code, values, styles and history");
 require(withDialog(model,view,[](QDialog* dialog){dialog->accept();})&&session.snapshot()==before&&!session.canUndo(),"accepting untouched imported Accounting preserves its exact escaped source code without a history entry");
 require(withDialog(model,view,[](QDialog* dialog){auto* categories=dialog->findChild<QListWidget*>("formatCells.categoryList");QTest::keyClick(categories,Qt::Key_Home);for(int i=0;i<3;++i)QTest::keyClick(categories,Qt::Key_Down);auto* symbol=dialog->findChild<QComboBox*>("formatCells.currencySymbol");require(symbol->currentData()=="$","reselecting Accounting preserves the decoded dollar symbol");QTest::keyClick(symbol,Qt::Key_Home);require(symbol->currentData()=="","the observed Home command selects None without a currency-symbol exception");dialog->accept();}),"imported Accounting can be reselected and changed to None through actual category and symbol keys");
 require(model.cellStyle(0,0).at("numberFormat")==accountingNumberFormat(0,"")&&model.cellStyle(0,1).at("numberFormat")==accountingNumberFormat(0,"")&&model.raw(0,0)=="5648"&&model.raw(0,1)=="=1+2"&&model.cellStyle(0,0).at("bold")==true&&model.cellStyle(0,1).at("italic")==true,"Accounting changes only the selected numeric display, retaining formulas and mixed font styles");
 require(session.undo(),"the imported Accounting adjustment is one undo");model.refresh();require(session.snapshotView().at("sheets")==book.at("sheets")&&!session.canUndo(),"one undo restores the exact imported escaped-dollar code and all selected content");
}
