 require(model.cellStyle(0,0).at("note")=="Keep this note"&&model.cellStyle(0,0).at("bold")==true&&model.cellStyle(0,1).at("italic")==true&&model.raw(0,1)=="=1+2"&&model.cellStyle(2,0).empty(),"borders preserve notes, formulas, unrelated styles and cells outside the range");
